mapper.select:
select p.FINPROD_ID id, p.FINPROD_ABBR text from FIN_PRODUCT p
1=1
AND FINPROD_ID = #{initValue}
and FINPROD_TYPE =#{finprodType}
AND (FINPROD_ID like concat('%',concat(#{search},'%')) OR FINPROD_ABBR like concat('%',concat(#{search},'%')))

select FINPROD_MARKET_ID id, FINPROD_ABBR text from FIN_PRODUCT
1=1
AND FINPROD_MARKET_ID = #{initValue}
and FINPROD_TYPE = #{assetType}
AND (FINPROD_MARKET_ID like concat('%',concat(#{search},'%')) OR FINPROD_ABBR like concat('%',concat(#{search},'%')))

SELECT distinct COUNTER_ID AS id, COUNTER_NAME AS text FROM MST_COUNTER_PARTY
(COUNTER_ID LIKE CONCAT('%',CONCAT(#{search,jdbcType=VARCHAR},'%')) or COUNTER_NAME LIKE CONCAT('%',CONCAT(#{search,jdbcType=VARCHAR},'%')) )
AND COUNTER_ID = #{initValue,jdbcType=VARCHAR}
